import{_ as n,C as o,o as r,c as s,j as e,a as d,E as i,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const _=JSON.parse('{"title":"Grafana, Prometheus and Loki","description":"","frontmatter":{},"headers":[],"relativePath":"connections/monitoring.md","filePath":"connections/monitoring.md"}'),c={name:"connections/monitoring.md"};function l(p,t,g,m,f,u){const a=o("Badge");return r(),s("div",null,[t[0]||(t[0]=e("h1",{id:"grafana-prometheus-and-loki",tabindex:"-1"},[d("Grafana, Prometheus and Loki "),e("a",{class:"header-anchor",href:"#grafana-prometheus-and-loki","aria-label":'Permalink to "Grafana, Prometheus and Loki"'},"​")],-1)),i(a,{type:"built",text:"Built"}),t[1]||(t[1]=h(' Agents can read live from your monitoring: alerts, dashboards, metrics and logs. This page is about those reads. For Octryx AI&#39;s own metrics, see <a href="/docs/install/metrics">Metrics for Prometheus</a>.<h2 id="set-it-up" tabindex="-1">Set it up <a class="header-anchor" href="#set-it-up" aria-label="Permalink to &quot;Set it up&quot;">​</a></h2><p><strong>Admin › Connections › Add connection</strong>, with one connection per instance:</p><table tabindex="0"><thead><tr><th>Type</th><th>Fields</th></tr></thead><tbody><tr><td><strong>Grafana</strong></td><td><strong>Grafana URL</strong> and an <strong>API token</strong></td></tr><tr><td><strong>Prometheus</strong></td><td>the URL; no sign-in</td></tr><tr><td><strong>Loki</strong></td><td>the URL; no sign-in</td></tr></tbody></table><p>Bind each connection to an <strong>instance label</strong>, for example <code>prod-eu</code>. An agent&#39;s call names the instance; a call without one is refused with the list of candidates, so an agent never reads the wrong environment by accident.</p><p>The <strong>Test</strong> button is not offered for these types yet.</p><h2 id="what-agents-can-do" tabindex="-1">What agents can do <a class="header-anchor" href="#what-agents-can-do" aria-label="Permalink to &quot;What agents can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th><th>Kind</th></tr></thead><tbody><tr><td>read Grafana alert, list Grafana alerts</td><td>alerts and their state</td><td>read</td></tr><tr><td>get dashboard JSON</td><td>a dashboard&#39;s definition</td><td>read</td></tr><tr><td>render panel as image</td><td>a panel as a picture, for the answer</td><td>read</td></tr><tr><td>create snapshot</td><td>a Grafana snapshot to share</td><td>write, needs confirmation</td></tr><tr><td>query Prometheus</td><td>a PromQL query over at most 24 hours and at most 1,000 points</td><td>read</td></tr><tr><td>query Loki</td><td>a LogQL query</td><td>read</td></tr></tbody></table><p>These reads are what the <strong>Incident / alert analysis</strong> workflow (shipped, but off on a fresh installation; a platform admin switches it on in <strong>Agents › Workflows</strong>) uses to collect evidence before it proposes a hypothesis; the hypothesis must cite its evidence.</p>',11))])}const y=n(c,[["render",l]]);export{_ as __pageData,y as default};
